WITH base AS (SELECT *, CASE WHEN page = '/home' THEN 1 ELSE 0 END AS is_home FROM web_events WHERE duration_sec BETWEEN 307 AND 386), prev_events AS (SELECT *, LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) AS prev_event_time FROM base), with_gaps AS (SELECT *, CASE WHEN prev_event_time IS NULL OR event_time > prev_event_time + INTERVAL '30' DAY THEN 1 ELSE 0 END AS new_group_flag FROM prev_events), islands AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT session_id, COUNT(CASE WHEN page = '/search' THEN 1 END) AS search_count, SORT_ARRAY(COLLECT_SET(event_type)) AS event_type_list, COUNT(DISTINCT session_id) AS distinct_session_ids, MIN(session_no) AS min_session_no, COUNT_IF(event_type = 'search') AS search_events FROM islands GROUP BY session_id ORDER BY search_events DESC NULLS LAST;
